function ProfileWorkspace({ channel, profile, audience, performance, safety, compact, l }: { channel: typeof creatorProfiles[string]["channels"][number]; profile: typeof creatorProfiles[string]; audience: typeof creatorProfiles[string]["audienceProfiles"][string]; performance: typeof creatorProfiles[string]["contentPerformance"][string]; safety: typeof creatorProfiles[string]["brandSafety"][string]; compact: (value: number) => string; l: ReturnType<typeof useLoc> }) { return <div className="space-y-5"><div className="grid gap-3 md:grid-cols-4"><DrawerStat label={l(L.followersLabel)} value={compact(channel.followerCount)} /><DrawerStat label={l(L.engagement)} value={`${channel.avgEngagementRate}%`} /><DrawerStat label={l(L.views)} value={compact(channel.avgViews)} /><DrawerStat label="CPE" value={`$${profile.commercialInfo.avgCpe}`} /></div><div className="grid gap-4 lg:grid-cols-[minmax(0,1.5fr)_minmax(280px,.85fr)]"><DrawerBlock title={l({ zh: "受众画像", en: "Engaged audience" })}><div className="grid gap-4 sm:grid-cols-3"><div className="space-y-2">{audience.geoDistribution.slice(0, 3).map((item) => <PercentRow key={item.label} label={item.label} value={item.percentage} />)}</div><div className="space-y-2">{audience.ageDistribution.map((item) => <PercentRow key={item.label} label={item.label} value={item.percentage} />)}</div><div className="rounded-[9px] bg-page p-3"><p className="text-[9px] text-muted">{l({ zh: "性别分布", en: "Gender" })}</p><strong className="mt-3 block text-[24px] text-brand">{audience.genderDistribution[0].percentage}%</strong><p className="text-[10px] text-slate">{audience.genderDistribution[0].label}</p><div className="mt-3 flex flex-wrap gap-1">{audience.audienceInterests.slice(0, 3).map((item) => <span key={item} className="rounded-full bg-white px-2 py-1 text-[8px] text-slate">{item}</span>)}</div></div></div></DrawerBlock><DrawerBlock title={l({ zh: "品牌安全", en: "Brand safety" })}><div className="space-y-3"><div className="flex items-center justify-between"><strong className="text-[14px] text-teal-text">{safety.safetyOverview}</strong><span className="text-[9px] text-slate">{safety.complianceStatus}</span></div>{safety.riskDetection.map((risk) => <div key={risk.label} className="flex items-center justify-between text-[10px]"><span className="text-slate">{risk.label}</span><span className="rounded-full bg-soft-teal px-2 py-0.5 text-[8px] font-semibold text-teal-text">{risk.level}</span></div>)}</div></DrawerBlock></div><div className="grid gap-4 lg:grid-cols-[minmax(0,1.5fr)_minmax(280px,.85fr)]"><DrawerBlock title={l(L.works)}><div className="grid grid-cols-2 gap-3">{performance.recentContents.slice(0, 2).map((item, index) => <article key={item.title} className="overflow-hidden rounded-[10px] border border-border"><img src={["https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=640&q=80", "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=640&q=80"][index]} alt="" className="h-32 w-full object-cover" /><div className="p-3"><p className="text-[11px] font-semibold text-ink">{item.title}</p><p className="mt-1 text-[9px] text-muted">{compact(item.views)} {l({ zh: "播放", en: "views" })} · {compact(item.engagements)} {l({ zh: "互动", en: "engagements" })}</p></div></article>)}</div></DrawerBlock><DrawerBlock title={l({ zh: "品牌提及表现", en: "Brand mention performance" })}><div className="space-y-3"><DrawerKey label={l({ zh: "平均互动率", en: "Avg. engagement" })} value={`${performance.brandMentionPerf.engagementRate}%`} /><DrawerKey label={l({ zh: "有效率", en: "Effectiveness" })} value={`${performance.brandMentionPerf.effectiveness}%`} /><DrawerKey label={l({ zh: "饱和度", en: "Saturation" })} value={`${performance.brandMentionPerf.saturation}%`} /></div></DrawerBlock></div><div className="grid gap-4 lg:grid-cols-[minmax(0,1.5fr)_minmax(280px,.85fr)]"><DrawerBlock title={l({ zh: "同类达人对标", en: "Peer comparison" })}><div className="space-y-3">{Object.entries(performance.peerPercentile).map(([key, value]) => <PercentRow key={key} label={key} value={value} />)}</div></DrawerBlock><DrawerBlock title={l({ zh: "发布时间表现", en: "Publishing pattern" })}><div className="space-y-3">{performance.publishTimePattern.map((item) => <PercentRow key={item.label} label={item.label} value={item.score} />)}</div></DrawerBlock></div></div>; }
function ProfileAudience({ audience, l }: { audience: typeof creatorProfiles[string]["audienceProfiles"][string]; l: ReturnType<typeof useLoc> }) { return <div className="space-y-4"><DrawerBlock title={l({ zh: "核心受众", en: "Core audience" })}><div className="space-y-3">{audience.genderDistribution.map((item) => <PercentRow key={item.label} label={item.label} value={item.percentage} />)}</div></DrawerBlock><DrawerBlock title={l({ zh: "地域分布", en: "Geography" })}><div className="flex flex-wrap gap-2">{audience.geoDistribution.map((item) => <span key={item.label} className="rounded-[8px] bg-page px-3 py-2 text-[10px] text-slate">{item.label} <strong className="ml-1 text-ink">{item.percentage}%</strong></span>)}</div></DrawerBlock><DrawerBlock title={l({ zh: "年龄与兴趣", en: "Age & interests" })}><div className="flex flex-wrap gap-1.5">{[...audience.ageDistribution.map((item) => `${item.label} ${item.percentage}%`), ...audience.audienceInterests].map((item) => <span key={item} className="rounded-full bg-soft-pink px-2.5 py-1 text-[9.5px] text-brand">{item}</span>)}</div></DrawerBlock></div>; }
function ProfilePerformance({ performance, compact, l }: { performance: typeof creatorProfiles[string]["contentPerformance"][string]; compact: (value: number) => string; l: ReturnType<typeof useLoc> }) { return <div className="space-y-4"><DrawerBlock title={l(L.works)}><div className="space-y-2">{performance.recentContents.map((item) => <div key={item.title} className="flex items-center justify-between rounded-[9px] border border-border bg-white px-3 py-2.5"><div><p className="text-[11px] font-semibold text-ink">{item.title}</p><p className="mt-0.5 text-[9px] text-muted">{item.type} · {item.publishedAt}</p></div><div className="text-right text-[9px] text-muted"><p>{compact(item.views)} {l({ zh: "播放", en: "views" })}</p><strong className="text-ink">{compact(item.engagements)} {l({ zh: "互动", en: "eng." })}</strong></div></div>)}</div></DrawerBlock><div className="grid grid-cols-2 gap-3"><DrawerBlock title={l({ zh: "品牌提及", en: "Brand mentions" })}><p className="text-[18px] font-bold text-navy">{performance.brandMentionPerf.engagementRate}%</p><p className="mt-1 text-[9px] text-slate">{l({ zh: "有效率", en: "Effectiveness" })} {performance.brandMentionPerf.effectiveness}%</p></DrawerBlock><DrawerBlock title={l({ zh: "同类百分位", en: "Peer percentile" })}><p className="text-[18px] font-bold text-navy">P{performance.peerPercentile.engagement}</p><p className="mt-1 text-[9px] text-slate">{l(L.engagement)} · {l({ zh: "领先同类", en: "vs. peers" })}</p></DrawerBlock></div></div>; }
function ProfileCommercial({ profile, l }: { profile: typeof creatorProfiles[string]; l: ReturnType<typeof useLoc> }) { const info = profile.commercialInfo; return <div className="space-y-4"><div className="grid grid-cols-3 gap-2"><DrawerStat label={l({ zh: "预估报价", en: "Est. rate" })} value={info.estimatedPriceRange} /><DrawerStat label="CPE" value={`$${info.avgCpe}`} /><DrawerStat label="CPM" value={`$${info.avgCpm}`} /></div><DrawerBlock title={l({ zh: "合作品牌", en: "Brand history" })}><div className="flex flex-wrap gap-1.5">{info.cooperatedBrands.map((brand) => <span key={brand} className="rounded-[7px] border border-border bg-white px-2.5 py-1.5 text-[10px] font-semibold text-ink">{brand}</span>)}</div></DrawerBlock><DrawerBlock title={l({ zh: "商务资料", en: "Business details" })}><div className="space-y-2 text-[10.5px]"><DrawerKey label={l({ zh: "合作邮箱", en: "Contact email" })} value={info.contactEmail.replace(/(^.).*(@.*$)/, "$1••••$2")} /><DrawerKey label={l({ zh: "收货地址", en: "Shipping address" })} value={info.shippingAddress.saved ? l({ zh: "已保存，仅授权成员可见", en: "Saved — authorized members only" }) : "—"} /></div></DrawerBlock></div>; }
function ProfileManagement({ profile, l }: { profile: typeof creatorProfiles[string]; l: ReturnType<typeof useLoc> }) { const management = profile.systemManagement; return <div className="space-y-4"><DrawerBlock title={l({ zh: "平台管理", en: "Workspace management" })}><div className="grid grid-cols-2 gap-2"><DrawerKey label={l({ zh: "所属项目", en: "Campaign" })} value={management.campaignId} /><DrawerKey label={l({ zh: "负责人", en: "Owner" })} value={management.owner} /><DrawerKey label={l({ zh: "分组", en: "Group" })} value={management.groupTag} /><DrawerKey label={l({ zh: "自定义评分", en: "Custom rating" })} value={`${"★".repeat(management.customRating)}${"☆".repeat(5 - management.customRating)}`} /></div></DrawerBlock><DrawerBlock title={l({ zh: "自定义标签", en: "Custom tags" })}><div className="flex flex-wrap gap-1.5">{management.customTags.map((tag) => <span key={tag} className="rounded-full bg-soft-pink px-2.5 py-1 text-[9.5px] text-brand">{tag}</span>)}</div></DrawerBlock><DrawerBlock title={l({ zh: "操作记录", en: "Activity" })}><div className="space-y-2">{management.operationLogs.map((log) => <div key={`${log.at}-${log.type}`} className="flex items-center justify-between text-[10px]"><span className="text-slate">{log.type} · {log.operator}</span><span className="text-muted">{log.at}</span></div>)}</div></DrawerBlock></div>; }
function DrawerBlock({ title, children }: { title: string; children: React.ReactNode }) { return <section className="rounded-[11px] border border-border bg-white p-3.5"><h3 className="mb-3 text-[11.5px] font-semibold text-ink">{title}</h3>{children}</section>; }
function DrawerKey({ label, value }: { label: string; value: string }) { return <div className="rounded-[8px] bg-page px-3 py-2"><p className="text-[8.5px] text-muted">{label}</p><p className="mt-1 truncate text-[10.5px] font-semibold text-ink">{value}</p></div>; }
function PercentRow({ label, value }: { label: string; value: number }) { return <div><div className="mb-1 flex justify-between text-[10px]"><span className="text-slate">{label}</span><strong className="text-ink">{value}%</strong></div><div className="h-1.5 overflow-hidden rounded-full bg-page"><span className="block h-full rounded-full bg-brand" style={{ width: `${value}%` }} /></div></div>; }

function CreatorDetailsDrawer({ creator, onClose }: { creator: typeof creators[number]; onClose: () => void }) {
  const l = useLoc();
  const [platform, setPlatform] = useState(creator.platform);
  const platforms = Array.from(new Set([creator.platform, "Instagram", "TikTok", "YouTube"]));
  const compact = (value: number) => value >= 1000 ? `${Math.round(value / 1000)}K` : String(value);
  const followers = platform === creator.platform ? creator.followers : Math.round(creator.followers * 0.46);
  const views = Math.round(followers * (0.18 + creator.engagement / 100));
  const works = platform === "YouTube" ? ["Video", "Short", "Live"] : platform === "Instagram" ? ["Reel", "Post", "Story"] : ["Video", "Post", "Video"];
  return <><button type="button" aria-label="Close creator details" onClick={onClose} className="fixed inset-0 z-40 cursor-default bg-navy/10 backdrop-blur-[1px]" /><aside aria-label={l({ zh: "达人详情", en: "Creator details" })} className="fixed inset-y-0 right-0 z-50 flex w-full max-w-[500px] flex-col border-l border-border bg-surface shadow-[-18px_0_46px_rgba(25,37,63,0.10)]"><header className="flex items-center justify-between border-b border-border bg-white px-6 py-4"><strong className="text-[15px] text-ink">{l({ zh: "达人详情", en: "Creator details" })}</strong><button type="button" aria-label={l({ zh: "关闭", en: "Close" })} onClick={onClose} className="flex h-8 w-8 items-center justify-center rounded-[8px] text-slate hover:bg-page hover:text-ink"><X className="h-4 w-4" /></button></header><div className="flex-1 overflow-y-auto px-6 py-6"><section className="flex items-start gap-3.5"><img src={creator.avatar} alt="" className="h-14 w-14 rounded-full object-cover" /><div className="min-w-0"><h2 className="text-[18px] font-bold tracking-[-0.03em] text-navy">{creator.name}</h2><p className="mt-0.5 text-[11px] text-muted">{creator.handle}</p><p className="mt-2 text-[10px] text-slate">{l(L.location)} · {l(creator.reason)}</p></div></section><section className="mt-7 border-t border-border pt-5"><h3 className="text-[13px] font-semibold text-ink">{l(L.platform)}</h3><div className="mt-3 flex flex-wrap gap-1.5">{platforms.map((item) => <button key={item} type="button" onClick={() => setPlatform(item)} className={`rounded-[7px] border px-3 py-1.5 text-[10px] font-medium ${platform === item ? "border-brand/25 bg-soft-pink text-brand" : "border-border bg-white text-slate hover:text-ink"}`}>{item}</button>)}</div><div className="mt-4 grid grid-cols-3 gap-2"><DrawerStat label={l(L.followersLabel)} value={compact(followers)} /><DrawerStat label={l(L.engagement)} value={`${platform === creator.platform ? creator.engagement : Math.max(2.6, creator.engagement - 2.1).toFixed(1)}%`} /><DrawerStat label={l(L.views)} value={compact(views)} /></div></section><section className="mt-7 border-t border-border pt-5"><h3 className="text-[13px] font-semibold text-ink">{l(L.works)}</h3><div className="mt-3 grid grid-cols-3 gap-2">{works.map((work, index) => <div key={`${work}-${index}`} className="relative aspect-[.82] overflow-hidden rounded-[9px] bg-page"><img src={creator.avatar} alt="" className="h-full w-full object-cover" style={{ objectPosition: `${30 + index * 24}% center` }} /><span className="absolute inset-x-0 bottom-0 bg-navy/70 py-1 text-center text-[9px] font-medium text-white">{work}</span></div>)}</div></section><section className="mt-7 border-t border-border pt-5"><h3 className="text-[13px] font-semibold text-ink">{l({ zh: "合作表现", en: "Collaboration performance" })}</h3><div className="mt-3 divide-y divide-border overflow-hidden rounded-[10px] border border-border bg-white"><DrawerStatRow label={l(L.delivery)} value={`${96 - (creator.collaborations ?? 0)}%`} /><DrawerStatRow label={l({ zh: "合作次数", en: "Collaborations" })} value={String((creator.collaborations ?? 0) + 8)} /><DrawerStatRow label={l({ zh: "匹配建议", en: "Recommendation" })} value={l({ zh: "优先建联", en: "Priority" })} /></div></section></div><footer className="border-t border-border bg-white px-6 py-4"><Button className="w-full"><BookmarkPlus className="h-3.5 w-3.5" />{l(L.add)}</Button></footer></aside></>;
}
function DrawerStat({ label, value }: { label: string; value: string }) { return <div className="rounded-[9px] bg-page px-3 py-3"><p className="text-[9px] text-muted">{label}</p><strong className="mt-1.5 block text-[14px] text-ink">{value}</strong></div>; }
function DrawerStatRow({ label, value }: { label: string; value: string }) { return <div className="flex items-center justify-between px-4 py-3"><span className="text-[11px] text-slate">{label}</span><strong className="text-[12px] text-ink">{value}</strong></div>; }

function CreatorRow({ creator, index, selected, onToggle, onView }: { creator: typeof creators[number]; index: number; selected: boolean; onToggle: () => void; onView?: () => void }) {
  const l = useLoc();
  const profile = creatorProfiles[creator.id];
  const primaryChannel = profile.channels[0];
  const audience = profile.audienceProfiles[primaryChannel.channelId];
  const coverImages = ["https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=420&q=80", "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=420&q=80", "https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=420&q=80"];
  const workImages = [coverImages[index % 3], coverImages[(index + 1) % 3]];
  return <article className="grid min-h-[176px] overflow-hidden rounded-[15px] border border-border bg-white transition-shadow hover:shadow-[0_10px_24px_rgba(25,37,63,0.06)] xl:grid-cols-[200px_minmax(290px,1.2fr)_minmax(230px,.85fr)_110px_minmax(170px,.7fr)_160px]">
    <div className="relative min-h-[176px] bg-page"><img src={creator.avatar} alt="" className="h-full w-full object-cover" /><div className="absolute inset-x-4 -bottom-3 flex rounded-[9px] border border-border bg-white p-1 shadow-sm"><button type="button" className="flex flex-1 items-center justify-center rounded-[6px] py-1 text-brand">×</button><button type="button" className="flex flex-1 items-center justify-center rounded-[6px] py-1 text-slate">↻</button></div></div>
    <div className="min-w-0 px-5 py-5"><div className="flex items-center gap-2"><h3 className="truncate text-[15px] font-bold text-ink">{creator.name}</h3><span className="rounded bg-page px-1.5 py-0.5 text-[9px] text-muted">{creator.handle}</span></div><div className="mt-2 flex items-center gap-1.5 text-[10px] text-slate"><MapPin className="h-3 w-3" />{profile.main.residentCountry}<span className="mx-1 text-border">|</span><span className="text-teal-text">●</span>{primaryChannel.isVerified ? l({ zh: "已认证", en: "Verified" }) : l({ zh: "待认证", en: "Unverified" })}</div><p className="mt-4 line-clamp-2 text-[10.5px] leading-4 text-slate">{l(creator.reason)}</p><div className="mt-3 flex flex-wrap gap-1.5">{profile.main.coreCategories.map((tag) => <span key={tag} className="rounded-full bg-page px-2 py-0.5 text-[9px] font-medium text-slate">{tag}</span>)}</div></div>
    <div className="flex items-center gap-2 border-l border-border px-4 py-4">{workImages.map((src, work) => <div key={src} className="relative h-[118px] flex-1 overflow-hidden rounded-[9px] bg-page"><img src={src} alt="" className="h-full w-full object-cover" /><span className="absolute right-1.5 top-1.5 rounded bg-white/90 px-1 py-0.5 text-[8px] font-semibold text-ink">{work === 0 ? primaryChannel.platform : "TikTok"}</span><span className="absolute inset-x-0 bottom-0 bg-navy/65 px-2 py-1 text-[8px] text-white">{performanceTitle(work)}</span></div>)}</div>
    <div className="flex flex-col justify-center border-l border-border px-4 py-4 text-[10px]"><strong className="text-[18px] text-teal-text">{profile.main.authenticityScore}%</strong><span className="mt-0.5 text-slate">{l({ zh: "账号真实度", en: "Account quality" })}</span><span className="mt-1 text-[9px] text-muted">{audience.genderDistribution[0].percentage}% {audience.genderDistribution[0].label}</span></div>
    <div className="flex flex-col justify-center gap-2 border-l border-border px-4 py-4">{profile.channels.slice(0, 2).map((channel) => <div key={channel.channelId} className="grid grid-cols-[auto_1fr_auto] gap-2 text-[10px]"><span className="font-semibold text-ink">{channel.platform}</span><span className="text-slate">{Math.round(channel.followerCount / 1000)}K</span><span className="text-slate">{channel.avgEngagementRate}%</span></div>)}<div className="mt-1 flex flex-wrap gap-1"><span className="rounded-full bg-[#fff7df] px-2 py-1 text-[8.5px] font-semibold text-[#9a7000]">{profile.main.coreCategories[0]}</span></div></div>
    <div className="flex flex-col justify-center gap-2 border-l border-border px-4 py-4"><Button size="sm" variant="outline" onClick={onView}><Eye className="h-3.5 w-3.5" />{l(L.view)}</Button><Button size="sm" variant={selected ? "soft" : "primary"} onClick={onToggle}><BookmarkPlus className="h-3.5 w-3.5" />{l(selected ? L.added : L.add)}</Button></div>
  </article>;
}
function performanceTitle(index: number) { return index === 0 ? "Product review" : "Daily routine"; }
